import CryptoKit
import simd
import XCTest

/// A real building's package set (Q6431): the fixture is the exporter's own output (`bim.export.ar {set: true}` on the
/// made-up two-storey building of crates/engine/tests/suite/jobs/arexport_set.rs, regenerated by
/// Fixtures/regenerate.sh, never edited by hand). Opening, the four views' packages, scope changes, the frame,
/// follow-the-system on the graph across floors, known / inferred / unknown links, layer groups, Update by content
/// hash with marks kept, and every failure said plainly while the rest of the building keeps working.
final class PackageSetTests: XCTestCase {
    static let fixtures = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Fixtures")
    static var v1: URL { fixtures.appendingPathComponent("SyntheticSet") }
    static var v2: URL { fixtures.appendingPathComponent("SyntheticSetV2") }

    var dir: URL!
    override func setUpWithError() throws { dir = try TestSupport.tempDir() }
    override func tearDownWithError() throws { try? FileManager.default.removeItem(at: dir); StubServer.reset() }

    func model(_ root: URL = PackageSetTests.v1) throws -> PackageSetModel { try PackageSetModel(root: root) }

    /// A writable copy of the v1 fixture (for the failure cases).
    func copyOfSet() throws -> URL {
        let to = dir.appendingPathComponent("set-\(UUID().uuidString)")
        try FileManager.default.copyItem(at: Self.v1, to: to)
        return to
    }

    func loadAll(_ m: PackageSetModel) throws -> [LoadedPackage] { try m.index.allPackages.map { try m.load($0.name) } }

    // MARK: opening and the four views

    func testTheExportersSetOpensWithItsLevelsRoomsAndViews() throws {
        let m = try model()
        let i = m.index
        XCTAssertEqual(i.title, "Sample Building")
        XCTAssertEqual(i.levels.map(\.name), ["L1", "L2"])
        XCTAssertEqual(i.rooms.count, 8)
        XCTAssertEqual(i.views.defaultView, .mep)
        XCTAssertEqual(i.views.defaultDensity, .mains)
        XCTAssertEqual(i.packages(for: ViewState(view: .mep)), ["building-mep-mains"])
        XCTAssertEqual(i.packages(for: ViewState(view: .mep, density: .full)), ["building-mep-mains", "building-mep-full"])
        XCTAssertEqual(i.packages(for: ViewState(view: .architectural)), ["building-architectural"])
        XCTAssertEqual(i.packages(for: ViewState(view: .floor, level: 1)), ["levels/L2"])
        let r101 = try XCTUnwrap(i.rooms.first { $0.number == "101" })
        XCTAssertEqual(i.packages(for: ViewState(view: .room, level: 0, room: r101.id)), ["rooms/L1-101-GUEST"])
        XCTAssertGreaterThan(i.graph.count, 100)
        XCTAssertEqual(m.levels.map(\.short), ["1", "2"])
        XCTAssertEqual(m.levels[1].elevation, Float(10 * Units.metersPerFoot), accuracy: 0.001)
        // Every package of the set reads, and every room offers field alignment (real room packages).
        for p in try loadAll(m) { XCTAssertFalse(p.elements.isEmpty, p.name) }
        XCTAssertTrue(m.rooms.allSatisfy(\.hasPackage))
    }

    func testEachViewDrawsExactlyThePackagesTheIndexNamesAndNeverEverything() throws {
        let m = try model()
        let all = try loadAll(m)
        let b = m.building(with: all)
        let f = ViewFilter(packageSet: b, index: m.index)
        let on = LayerPrefs(off: [])
        var states = [ViewState(view: .architectural), ViewState(view: .mep), ViewState(view: .mep, density: .full)]
        for l in m.levels.indices { states.append(ViewState(view: .floor, level: l)) }
        for r in m.rooms { states.append(ViewState(view: .room, level: r.level, room: r.number)) }
        for st in states {
            let want = Set(m.index.packages(for: st))
            let drawn = f.drawn(st, prefs: on)
            XCTAssertFalse(drawn.isEmpty, "\(st)")
            for id in drawn { XCTAssertTrue(want.contains(b.element(id)?.package ?? ""), "\(st): \(id)") }
            XCTAssertLessThan(drawn.count, b.elements.count / 2, "no view draws every object: \(st)")
            // The limit applies even to an element asked for directly.
            for e in b.elements where !want.contains(e.package ?? "") { XCTAssertFalse(f.allows(e, st, prefs: on)) }
        }
        // MEP mains: gear, house panels and feeders; never walls, devices or furniture.
        let mains = f.drawn(ViewState(view: .mep), prefs: on).compactMap { b.element($0) }
        XCTAssertTrue(mains.contains { $0.part == .switchgear })
        XCTAssertFalse(mains.contains { $0.part == .wall || $0.part == .device || $0.layer == .furniture })
        // Full MEP adds the full package on top of the mains.
        let full = f.drawn(ViewState(view: .mep, density: .full), prefs: on)
        XCTAssertTrue(Set(mains.map(\.id)).isSubset(of: full))
        XCTAssertTrue(full.contains { b.element($0)?.package == "building-mep-full" })
    }

    func testOpeningLoadsOnlyTheDefaultViewAndTheExteriorAndLevelsAndRoomsComeOnDemand() async throws {
        let (m, opening, failed) = try await PackageSetModel.open(root: Self.v1)
        XCTAssertTrue(failed.isEmpty)
        XCTAssertEqual(Set(opening.map(\.name)), ["building-mep-mains", "building-architectural"])
        let b = m.building(with: opening)
        let onDemand = b.elements.filter { e in
            let p = e.package ?? ""
            return p.hasPrefix("levels/") || p.hasPrefix("rooms/")
        }
        XCTAssertTrue(onDemand.isEmpty)
        XCTAssertTrue(b.elements.contains { $0.part == .exterior }, "the reveal's exterior")
        XCTAssertTrue(b.elements.contains { $0.part == .outline }, "MEP's one outline")
        // A floor, then a room: each loads its own package.
        let l2 = try m.load("levels/L2")
        let withFloor = m.building(with: opening + [l2])
        XCTAssertTrue(withFloor.elements.contains { $0.package == "levels/L2" && $0.part == .roomTile })
        let tile = try XCTUnwrap(withFloor.elements.first { $0.package == "levels/L2" && $0.part == .roomTile })
        XCTAssertNotNil(withFloor.room(tile.sourceID), "a floor's tile is its room (tap target)")
    }

    func testLevelAndRoomPackagesShareTheBuildingFrame() throws {
        let m = try model()
        let l1 = try m.load("levels/L1")
        let r101 = try m.load("rooms/L1-101-GUEST")
        // A room's copy of a wall (full height, clipped to the room) and the level's copy (cut at 4 ft, so a door's
        // opening is open below the cut) are the same wall in the same frame: the same faces, overlapping along it.
        var shared = 0
        for e in r101.elements where e.part == .wall {
            guard let w = l1.elements.first(where: { $0.sourceID == e.sourceID }) else { continue }
            let a = e.shape.bounds, c = w.shape.bounds
            let thinX = a.max.x - a.min.x < a.max.z - a.min.z
            if thinX {
                XCTAssertEqual(a.min.x, c.min.x, accuracy: 0.01, e.sourceID); XCTAssertEqual(a.max.x, c.max.x, accuracy: 0.01, e.sourceID)
                XCTAssertTrue(min(a.max.z, c.max.z) > max(a.min.z, c.min.z), e.sourceID)
            } else {
                XCTAssertEqual(a.min.z, c.min.z, accuracy: 0.01, e.sourceID); XCTAssertEqual(a.max.z, c.max.z, accuracy: 0.01, e.sourceID)
                XCTAssertTrue(min(a.max.x, c.max.x) > max(a.min.x, c.min.x), e.sourceID)
            }
            XCTAssertEqual(a.min.y, c.min.y, accuracy: 0.01, "both stand on the floor")
            XCTAssertLessThanOrEqual(c.max.y, Float(4 * Units.metersPerFoot) + 0.01, "the level's copy is cut at 4 ft")
            shared += 1
        }
        XCTAssertGreaterThan(shared, 0)
        // A receptacle at plan (4, 0.8) ft on L1, from the room package (origin = its anchor), lands there.
        let rec = try XCTUnwrap(r101.elements.first { $0.circuit == "PU-1-1" && $0.part == .device && $0.kind == "Receptacle" })
        let want = m.index.modelPoint(planFeet: SIMD2(4, 0.8), elevationFeet: 0)
        XCTAssertEqual(rec.shape.anchor.x, want.x, accuracy: 0.15)
        XCTAssertEqual(rec.shape.anchor.z, want.z, accuracy: 0.15)
        // The room's rectangle (index bounds) holds its package's objects.
        let room = try XCTUnwrap(m.rooms.first { $0.displayNumber == "101" })
        XCTAssertTrue(room.contains(rec.shape.anchor, margin: 0.2))
        // Level and room copies are separate objects; the building copies keep the element id.
        XCTAssertTrue(l1.elements.allSatisfy { $0.id == "\($0.sourceID)|levels/L1" })
        XCTAssertTrue(try m.load("building-mep-mains").elements.allSatisfy { $0.id == $0.sourceID })
        // A floor is in MEP mains (its context) and in Architectural (its slab): both copies stay, each in its view.
        let both = m.building(with: [try m.load("building-mep-mains"), try m.load("building-architectural")])
        let f = ViewFilter(packageSet: both, index: m.index)
        let floors = both.elements.filter { $0.part == .slab }
        XCTAssertTrue(floors.contains { f.allows($0, ViewState(view: .architectural), prefs: .standard) })
        XCTAssertTrue(floors.contains { f.allows($0, ViewState(view: .mep), prefs: .standard) })
        XCTAssertEqual(Set(floors.map(\.id)).count, floors.count)
    }

    // MARK: follow the system (the graph)

    func testTraceRunsAcrossFloorsByElementIdWithoutLoadingAnyPackage() throws {
        let i = try model().index
        // A light on L2 → its panel on L1 → the switchboard (the source).
        let light = try XCTUnwrap(i.graph.first { $0.kind == "light_fixture" && $0.level == "L2" })
        let f = i.focus(light.id)
        guard case let .chain(steps) = f.trace else { return XCTFail("a chain") }
        XCTAssertEqual(steps.map(\.tag), ["A", "PH", "MDP"])
        XCTAssertEqual(steps.map(\.level), [1, 0, 0], "it crosses from L2 to L1")
        XCTAssertEqual(steps.first?.state, .known)
        XCTAssertNil(f.note, "the path ends at its source")
        XCTAssertTrue(f.lit.isSuperset(of: ["1BB", "1BA"]))
        // The panel lights what it feeds, across floors.
        let ph = i.focus("1BB")
        XCTAssertTrue(ph.showsDownstream)
        XCTAssertTrue(ph.lit.contains(light.id))
        XCTAssertGreaterThan(ph.downstreamCount, 3)
    }

    func testKnownInferredAndUnknownLinksAreToldApartAndNeverGuessed() throws {
        let i = try model().index
        XCTAssertGreaterThan(i.links.known, 0); XCTAssertGreaterThan(i.links.inferred, 0); XCTAssertGreaterThan(i.links.unknown, 0)
        // The receptacle whose panel a rule gave: its first link says inferred.
        let inf = try XCTUnwrap(i.graph.first { $0.fedBy.contains { $0.state == .inferred } })
        guard case let .chain(steps) = i.focus(inf.id).trace else { return XCTFail("a chain") }
        XCTAssertEqual(steps.first?.state, .inferred)
        XCTAssertEqual(steps.dropFirst().first?.tag, "PU-2")
        // A pipe nobody says feeds: a plain unknown, no path invented.
        let unknown = try XCTUnwrap(i.graph.first { $0.state == .unknown && $0.fedBy.isEmpty && $0.kind == "pipe" })
        let u = i.focus(unknown.id)
        guard case let .noKnownConnection(msg) = u.trace else { return XCTFail("unknown, said plainly: \(u.trace)") }
        XCTAssertTrue(msg.hasPrefix("Unknown: the documents don't say"), msg)
        XCTAssertEqual(u.lit, [unknown.id])
        // A device with a circuit but no panel: unknown, from its own link.
        if let c = i.graph.first(where: { $0.fedBy.contains { $0.state == .unknown && $0.circuit != nil } }) {
            XCTAssertNotNil(i.trace(c.id).note)
        }
    }

    // MARK: layers from the packages' node groups

    func testLayerSwitchesFollowTheNodeGroupsAndFurnitureIsOffAndOnlyInARoom() throws {
        let m = try model()
        let b = m.building(with: try loadAll(m))
        let f = ViewFilter(packageSet: b, index: m.index)
        let r101 = try XCTUnwrap(m.rooms.first { $0.displayNumber == "101" })
        let room = ViewState(view: .room, level: 0, room: r101.number)
        let std = LayerPrefs.standard
        XCTAssertEqual(m.index.groups["furniture"], false)
        let bed = try XCTUnwrap(b.elements.first { $0.layer == .furniture && $0.package == "rooms/L1-101-GUEST" })
        XCTAssertFalse(f.drawn(room, prefs: std).contains(bed.id), "furniture is off by default")
        XCTAssertTrue(f.drawn(room, prefs: LayerPrefs(off: [])).contains(bed.id))
        XCTAssertFalse(f.drawn(ViewState(view: .floor, level: 0), prefs: LayerPrefs(off: [])).contains { b.element($0)?.layer == .furniture })
        // Cabinets: floor and room only.
        XCTAssertTrue(f.drawn(ViewState(view: .floor, level: 0), prefs: std).contains { b.element($0)?.layer == .cabinets })
        XCTAssertFalse(f.drawn(ViewState(view: .mep, density: .full), prefs: LayerPrefs(off: [])).contains { b.element($0)?.layer == .cabinets })
        // Fire protection rides with Mechanical, as the export's groups say (the same switch as in AR).
        let fire = try XCTUnwrap(b.elements.first { $0.system == .fire })
        XCTAssertEqual(fire.layer, .mechanical)
        let mains = ViewState(view: .mep)
        XCTAssertTrue(f.drawn(mains, prefs: std).contains(fire.id) || !f.allows(fire, mains, prefs: std))
        XCTAssertFalse(f.drawn(mains, prefs: LayerPrefs(off: [.mechanical])).contains { b.element($0)?.system == .fire })
        // The shell has no switch.
        XCTAssertTrue(b.elements.filter(\.isBaseGroup).allSatisfy { $0.layer == nil })
    }

    func testAPipeWithNeitherRoleNorSizeShowsInFullMEPMarkedInferred() throws {
        let m = try model()
        let full = try m.load("building-mep-full")
        let inferred = full.elements.filter { $0.inferredNote != nil }
        XCTAssertEqual(inferred.count, 1)
        XCTAssertEqual(inferred.first?.part, .pipe)
        XCTAssertEqual(m.index.leftOut["pipe_size_unknown"], 0, "nothing dropped for an unknown size")
        let b = m.building(with: [try m.load("building-mep-mains"), full])
        XCTAssertTrue(ViewFilter(packageSet: b, index: m.index).drawn(ViewState(view: .mep, density: .full), prefs: .standard).contains(inferred[0].id))
    }

    // MARK: memory: load on demand, release what is not in view

    func testTheCacheStaysInsideItsBudgetAndNeverReleasesWhatIsInView() throws {
        let m = try model()
        let levels = try ["levels/L1", "levels/L2"].map(m.load)
        let rooms = try m.index.allPackages.filter(\.isRoom).map { try m.load($0.name) }
        let mains = try m.load("building-mep-mains")
        // A budget that holds the mains, one level and about two rooms.
        var c = PackageCache(budgetBytes: mains.bytes + levels.map(\.bytes).max()! + 2 * rooms.map(\.bytes).max()!)
        c.insert(mains, inView: ["building-mep-mains"])
        for (k, l) in levels.enumerated() {
            let released = c.insert(l, inView: ["building-mep-mains", l.name])
            XCTAssertTrue(c.has(l.name)); XCTAssertTrue(c.has("building-mep-mains"))
            if k == 1 { XCTAssertTrue(released.contains("levels/L1") || c.bytes <= c.budgetBytes) }
        }
        for r in rooms {
            c.insert(r, inView: ["building-mep-mains", "levels/L2", r.name])
            XCTAssertTrue(c.has(r.name))
            XCTAssertLessThanOrEqual(c.bytes, c.budgetBytes)
            XCTAssertLessThanOrEqual(c.loaded.values.filter { $0.kind == .room }.count, PackageCache.maxSpareRooms + 1)
        }
        XCTAssertTrue(c.has("building-mep-mains"))
    }

    // MARK: failures are plain, and the rest keeps working

    func testAMissingDamagedOrOlderPackageSaysSoAndTheRestStillOpens() throws {
        let root = try copyOfSet()
        let fm = FileManager.default
        try fm.removeItem(at: root.appendingPathComponent("levels/L2.glb"))
        var bad = try Data(contentsOf: root.appendingPathComponent("rooms/L1-102-GUEST.glb"))
        bad[bad.count / 2] ^= 0xFF
        try bad.write(to: root.appendingPathComponent("rooms/L1-102-GUEST.glb"))
        let m = try model(root)
        XCTAssertThrowsError(try m.load("levels/L2")) { e in
            XCTAssertEqual((e as? FieldError)?.message, "Level 2 is missing on this phone. Update to fetch it again; the rest of the building still works.")
        }
        XCTAssertThrowsError(try m.load("rooms/L1-102-GUEST")) { e in
            XCTAssertTrue(((e as? FieldError)?.message ?? "").contains("is damaged"), "\(e)")
        }
        // Everything else still loads.
        for p in m.index.allPackages where p.name != "levels/L2" && p.name != "rooms/L1-102-GUEST" { XCTAssertNoThrow(try m.load(p.name), p.name) }
    }

    func testAPackageFromAnOlderExportIsRefusedPlainly() throws {
        // A model with no package header (written before package sets), installed with a matching checksum.
        let root = try copyOfSet()
        let old = try TestSupport.triangleGLB(nodes: [["mesh": 0, "name": "x", "extras": ["id": "1", "kind": "receptacle"]]])
        try old.write(to: root.appendingPathComponent("levels/L1.glb"))
        var j = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: root.appendingPathComponent("building.json"))) as? [String: Any])
        var pk = try XCTUnwrap(j["packages"] as? [[String: Any]])
        for k in pk.indices where pk[k]["name"] as? String == "levels/L1" {
            var files = pk[k]["files"] as? [String: Any] ?? [:]
            var g = files["glb"] as? [String: Any] ?? [:]
            g["bytes"] = old.count
            g["sha256"] = SHA256.hash(data: old).map { String(format: "%02x", $0) }.joined()
            files["glb"] = g
            pk[k]["files"] = files
        }
        j["packages"] = pk
        try JSONSerialization.data(withJSONObject: j).write(to: root.appendingPathComponent("building.json"))
        let m = try model(root)
        XCTAssertThrowsError(try m.load("levels/L1")) { e in
            XCTAssertTrue(((e as? FieldError)?.message ?? "").contains("older version of CADaddy"), "\(e)")
        }
        XCTAssertNoThrow(try m.load("levels/L2"))
    }

    func testAnIndexWithNoViewsIsAnOlderVersionAndADamagedIndexIsSaid() throws {
        var j = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: Self.v1.appendingPathComponent("building.json"))) as? [String: Any])
        j["views"] = nil
        XCTAssertThrowsError(try PackageSetIndex.parse(JSONSerialization.data(withJSONObject: j))) { e in
            XCTAssertTrue(((e as? FieldError)?.message ?? "").contains("older version of CADaddy"), "\(e)")
        }
        j["schema"] = "cadaddy.ar.building/2"
        XCTAssertThrowsError(try PackageSetIndex.parse(JSONSerialization.data(withJSONObject: j))) { e in
            XCTAssertTrue(((e as? FieldError)?.message ?? "").contains("newer CADaddy"), "\(e)")
        }
        XCTAssertThrowsError(try PackageSetIndex.parse(Data("{not json".utf8))) { e in
            XCTAssertTrue(((e as? FieldError)?.message ?? "").contains("can't be read"), "\(e)")
        }
    }

    func testTheSessionOpensWhenTheArchitecturalPackageFailsButNotWhenTheDefaultViewDoes() async throws {
        let root = try copyOfSet()
        try FileManager.default.removeItem(at: root.appendingPathComponent("building-architectural.glb"))
        let (_, opening, failed) = try await PackageSetModel.open(root: root)
        XCTAssertEqual(opening.map(\.name), ["building-mep-mains"])
        XCTAssertEqual(failed.keys.sorted(), ["building-architectural"])
        try FileManager.default.removeItem(at: root.appendingPathComponent("building-mep-mains.glb"))
        do { _ = try await PackageSetModel.open(root: root); XCTFail("the default view must open") } catch let e as FieldError {
            XCTAssertTrue(e.message.contains("MEP mains model is missing"), e.message)
        }
    }

    // MARK: Update by content hash; marks survive

    func serve(_ root: URL, overlay: URL? = nil) throws {
        // The office folder: v1's files, with the v2 overlay (its index and its changed packages) on top.
        let fm = FileManager.default
        for base in [root] + (overlay.map { [$0] } ?? []) {
            for name in try fm.subpathsOfDirectory(atPath: base.path) {
                var d: ObjCBool = false
                let u = base.appendingPathComponent(name)
                guard fm.fileExists(atPath: u.path, isDirectory: &d), !d.boolValue else { continue }
                StubServer.set("/office/\(name)", .init(body: try Data(contentsOf: u)))
            }
        }
    }

    func testUpdatePullsOnlyChangedPackagesAndMarksStayOnTheirElements() async throws {
        let store = try PackageSetStore(root: dir.appendingPathComponent("sets"))
        let lib = try PackageLibrary(root: dir.appendingPathComponent("lib"))
        let c = URLSessionConfiguration.ephemeral
        c.protocolClasses = [StubServer.self]
        let up = SetUpdater(store: store, library: lib, configuration: c)
        let manifest = try UpdateServer.manifestURL("http://192.168.1.20:8000/office/")
        StubServer.reset()
        try serve(Self.v1)
        let first = try await XCTUnwrapAsync(try await up.run(manifestURL: manifest))
        XCTAssertEqual(first.added.count, 13)
        var rec = try XCTUnwrap(store.list().first)
        // Open room 101 in AR (a library package) and mark the receptacle and the bed.
        let r101 = try XCTUnwrap(try store.model(rec).index.rooms.first { $0.number == "101" })
        let (rec2, room) = try store.roomRecord(rec, room: r101.id, library: lib)
        rec = rec2
        let m = try store.model(rec)
        let pkg = try m.load("rooms/L1-101-GUEST")
        let receptacle = try XCTUnwrap(pkg.elements.first { $0.kind == "Receptacle" })
        let bed = try XCTUnwrap(pkg.elements.first { $0.layer == .furniture })
        try lib.saveMarks([Mark(elementID: receptacle.sourceID, status: .installed), Mark(elementID: bed.sourceID, status: .missing)], for: room)

        // The office re-exports with the bed taken out of 101: only that package's content hash changes.
        StubServer.reset()
        try serve(Self.v1, overlay: Self.v2)
        let second = try await XCTUnwrapAsync(try await up.run(manifestURL: manifest))
        XCTAssertEqual(second.updated, ["rooms/L1-101-GUEST"])
        XCTAssertEqual(second.unchanged.count, 12)
        XCTAssertTrue(second.failed.isEmpty, "\(second.failed)")
        let fetched = StubServer.served().filter { !$0.hasSuffix("building.json") }
        XCTAssertEqual(Set(fetched), ["/office/rooms/L1-101-GUEST.glb", "/office/rooms/L1-101-GUEST.json"], "only the changed package is pulled")
        XCTAssertEqual(store.list().count, 1, "the same building, updated in place")
        // Every package of the new version opens (unchanged files kept, the changed one new).
        let m2 = try store.model(try XCTUnwrap(store.list().first))
        for p in m2.index.allPackages { XCTAssertNoThrow(try m2.load(p.name), p.name) }
        XCTAssertFalse(try m2.load("rooms/L1-101-GUEST").elements.contains { $0.layer == .furniture })
        // Marks stay attached by element id; the bed's is kept, flagged gone.
        let marks = lib.marks(try XCTUnwrap(lib.list().first { $0.id == room.id }))
        XCTAssertEqual(marks.count, 2)
        XCTAssertEqual(marks.first { $0.elementID == receptacle.sourceID }?.elementGone, nil)
        XCTAssertEqual(marks.first { $0.elementID == bed.sourceID }?.elementGone, true)

        // A third run with nothing changed pulls nothing but the index.
        StubServer.reset()
        try serve(Self.v1, overlay: Self.v2)
        let third = try await XCTUnwrapAsync(try await up.run(manifestURL: manifest))
        XCTAssertEqual(third.unchanged.count, 13)
        XCTAssertEqual(StubServer.served().filter { !$0.hasSuffix("building.json") }, [])
    }

    func testAnOfficeWithoutABuildingIsNotAnErrorAndABadDownloadKeepsTheOldVersion() async throws {
        let store = try PackageSetStore(root: dir.appendingPathComponent("sets"))
        let c = URLSessionConfiguration.ephemeral
        c.protocolClasses = [StubServer.self]
        let up = SetUpdater(store: store, library: nil, configuration: c)
        let manifest = try UpdateServer.manifestURL("http://192.168.1.20:8000/office/")
        StubServer.reset()
        let none = try await up.run(manifestURL: manifest)
        XCTAssertNil(none)
        try serve(Self.v1)
        _ = try await up.run(manifestURL: manifest)
        // The changed package arrives damaged: it fails, the old version stays, the rest updates.
        StubServer.reset()
        try serve(Self.v1, overlay: Self.v2)
        StubServer.set("/office/rooms/L1-101-GUEST.glb", .init(body: Data("damaged".utf8)))
        let r = try await XCTUnwrapAsync(try await up.run(manifestURL: manifest))
        XCTAssertEqual(r.failed.map(\.name), ["rooms/L1-101-GUEST"])
        let m = try store.model(try XCTUnwrap(store.list().first))
        XCTAssertThrowsError(try m.load("rooms/L1-101-GUEST"), "the kept old file no longer matches the new index: said plainly")
        XCTAssertNoThrow(try m.load("rooms/L1-102-GUEST"))
    }

    func testImportFromFilesCopiesTheSetAndARoomBecomesALibraryPackage() throws {
        let store = try PackageSetStore(root: dir.appendingPathComponent("sets"))
        let lib = try PackageLibrary(root: dir.appendingPathComponent("lib"))
        XCTAssertTrue(PackageSetStore.isSet(Self.v1))
        let r = try store.importFolder(Self.v1)
        XCTAssertEqual(r.title, "Sample Building")
        let m = try store.model(r)
        for p in m.index.allPackages { XCTAssertNoThrow(try m.load(p.name)) }
        let room = try XCTUnwrap(m.index.rooms.first { $0.number == "201" })
        let (r2, pkg) = try store.roomRecord(r, room: room.id, library: lib)
        XCTAssertEqual(r2.roomRecords[room.id], pkg.id)
        XCTAssertNotNil(pkg.anchor, "the room's anchor, for field alignment")
        // The second time, the same package (its marks and saved alignment).
        XCTAssertEqual(try store.roomRecord(r2, room: room.id, library: lib).1.id, pkg.id)
    }

    // MARK: the generated scale set (format drift, size)

    /// The glTF JSON chunk of a .glb.
    static func gltf(_ url: URL) throws -> [String: Any] {
        let d = try Data(contentsOf: url)
        let len = Int(d[12]) | Int(d[13]) << 8 | Int(d[14]) << 16 | Int(d[15]) << 24
        return try XCTUnwrap(JSONSerialization.jsonObject(with: d.subdata(in: 20..<(20 + len))) as? [String: Any])
    }

    func keys(_ root: URL) throws -> (index: Set<String>, graph: Set<String>, link: Set<String>, node: Set<String>) {
        let j = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: root.appendingPathComponent("building.json"))) as? [String: Any])
        let g = ((j["graph"] as? [String: Any])?["elements"] as? [[String: Any]]) ?? []
        var node = Set<String>()
        let m = try PackageSetModel(root: root)
        for p in m.index.allPackages {
            guard let f = p.glb else { continue }
            for n in (try Self.gltf(root.appendingPathComponent(f.path))["nodes"] as? [[String: Any]]) ?? [] { node.formUnion((n["extras"] as? [String: Any])?.keys ?? [:].keys) }
        }
        let links = g.flatMap { ($0["fed_by"] as? [[String: Any]] ?? []) + ($0["serves"] as? [[String: Any]] ?? []) }
        return (Set(j.keys), Set(g.flatMap(\.keys)), Set(links.flatMap(\.keys)), node)
    }

    func testTheGeneratedSetReadsLikeTheExportersOwn() throws {
        let out = dir.appendingPathComponent("gen")
        try SyntheticSet.write(to: out, spec: .small)
        let gen = try keys(out), real = try keys(Self.v1)
        XCTAssertTrue(gen.index.isSubset(of: real.index), "index keys the exporter never writes: \(gen.index.subtracting(real.index))")
        XCTAssertTrue(gen.graph.isSubset(of: real.graph), "graph keys: \(gen.graph.subtracting(real.graph))")
        XCTAssertTrue(gen.link.isSubset(of: real.link), "link keys: \(gen.link.subtracting(real.link))")
        // Node extras: the exporter's own keys (plus `reveal` and the room tile's, which it writes on those nodes).
        XCTAssertTrue(gen.node.isSubset(of: real.node), "node keys: \(gen.node.subtracting(real.node))")
        let m = try PackageSetModel(root: out)
        for p in m.index.allPackages { XCTAssertNoThrow(try m.load(p.name), p.name) }
    }

    func testAGeneratedBuildingOfSixtyFourRoomsOpensFastAndStaysInsideItsBudget() async throws {
        let out = dir.appendingPathComponent("scale")
        try SyntheticSet.write(to: out, spec: .scale(rooms: 64))
        let t0 = Date()
        let (m, opening, _) = try await PackageSetModel.open(root: out)
        let openSeconds = Date().timeIntervalSince(t0)
        XCTAssertGreaterThan(m.index.graph.count, 90_000)
        XCTAssertEqual(m.index.rooms.count, 64)
        XCTAssertLessThan(openSeconds, 10, "opening reads the index and the default view only")
        // Visit every level and every room under a budget of a few levels: the cache never goes over it and never
        // drops what is in view.
        let levelBytes = try m.load("levels/L1").bytes
        var c = PackageCache(budgetBytes: opening.reduce(0) { $0 + $1.bytes } + 2 * levelBytes + 8 * 1024 * 1024)
        for p in opening { c.insert(p, inView: Set(opening.map(\.name))) }
        for l in m.index.levels {
            let name = try XCTUnwrap(m.index.views.floorByLevel[l.name]?.first)
            let inView = Set(opening.map(\.name) + [name])
            c.insert(try m.load(name), inView: inView)
            XCTAssertLessThanOrEqual(c.bytes, c.budgetBytes)
            for r in m.index.rooms where r.level == l.name {
                let rn = try XCTUnwrap(r.package)
                c.insert(try m.load(rn), inView: inView.union([rn]))
                XCTAssertTrue(c.has(rn) && c.has(name))
                XCTAssertLessThanOrEqual(c.bytes, c.budgetBytes)
            }
        }
        print(String(format: "SCALE 64 rooms: graph %d, open %.2f s, cache %d MB of %d MB", m.index.graph.count, openSeconds, c.bytes >> 20, c.budgetBytes >> 20))
    }
}

func XCTUnwrapAsync<T>(_ v: @autoclosure () async throws -> T?, file: StaticString = #filePath, line: UInt = #line) async throws -> T {
    let x = try await v()
    return try XCTUnwrap(x, file: file, line: line)
}
